"""Finalize the fresh corrected-runtime comparison; preserve earlier R3 history."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'bench/reports/r3-benchmark';LIVE=OUT/'live-verification'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def main():
 s=read(LIVE/'summary.json');g=read(LIVE/'gain-review-input.json');release=read(LIVE/'release-execution.json')
 assert len(release['runs'])==2 and all(r['exit_code']==0 for r in release['runs'])
 assert [r['strict_verifier_exit_code'] for r in release['runs']]==[0,1]
 assert all(r['changes']==0 for r in release['runs'])
 assert all(r['same_reviewed_url'] and r['previous_review']['verdict']=='correct' for r in g['websites'])
 assert all(r['previous_review']['verdict']=='correct' for r in g['social'])
 assert read(LIVE/'loss-replay-main.json')==read(LIVE/'loss-replay-corrected.json')
 clone=ROOT/'bench/cache/r3-corrected-release'
 for n in (1,2):
  for name in ('envelopes.jsonl','profiles.jsonl'):
   count=sum(bool(line.strip()) for line in (clone/f'validation/run{n}'/name).open(encoding='utf8'))
   assert count==103
 review={'new_website_gains':len(g['websites']),'new_social_profile_additions':len(g['social']),'newly_unreviewed_gains':0,'inherited_correct_verdicts':len(g['websites'])+len(g['social']),'wrong':0,'doubtful':0,'highlighted_baseline_sites_retained':g['highlighted'],'method':'Exact company and website/social URL lookup against committed REVIEW.md ledgers; every live gain had already been reviewed correct. Current ownership proof excerpts retained in gain-review-input.json. No prior doubtful/wrong item is inherited.'}
 (LIVE/'review-result.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 lines=['## Fresh live corrected verification — 12 November 2026','','The corrected runtime `81086a9` was run once with the same README command, frozen 1,000-company bytes and defaults, fresh empty state, no bulk and stripped credentials. Exit 0; 1,000 envelopes and profiles; input SHA-256 unchanged. These are live measurements, replacing the earlier projection as the current measured result. No production code changed during this verification.','','| Metric | Main `abc33af` | Corrected `81086a9` |','|---|---:|---:|']
 for title,key in [('Websites','websites'),('Social companies','social_companies'),('Jobs companies (NAV or company-site)','jobs'),('Activity companies','activity'),('Distinct available facts','facts'),('HTTP total','http_total'),('HTTP mean/input','http_mean'),('HTTP max/company','http_max'),('Wall seconds, full process','wall_seconds'),('Deadline hits','deadline_hits')]:
  a=s['baseline'][key];b=s['candidate'][key]
  if isinstance(a,float):a=f'{a:.3f}';b=f'{b:.3f}'
  lines.append(f'| {title} | {a} | {b} |')
 lines+=['| Site warnings | none | none |','| All report warnings | none | none |','| Envelopes / profiles | 1,000 / 1,000 | 1,000 / 1,000 |','','The full-process wall time includes site construction, output and shutdown, and is higher than the earlier run. `report.runtime_ms` is 1,165.922 s (baseline 806.765 s), before the full site/end-to-end interval; the generated site is 762,927,741 bytes versus 757,791,285. This is not an isolated CPU/network timing experiment: an unrelated pre-existing Common Crawl worker was observed and left untouched, and an initial offline envelope scan overlapped late publication. No speed improvement is claimed. Both source snapshots and all measured timings remain unchanged.','','### Baseline websites missing now','','Exactly two baseline website companies are missing. Neither loss reproduces as a difference between main and corrected ownership code on the same saved evidence. No R3 regression fix was necessary; existing vetoes were preserved.','','| Company | Orgnr | Baseline URL | Reason / replay |','|---|---|---|---|','| ISTAD ART SOLUTION NORWAY NUF | 911691248 | https://www.pederistad.no | Homepage HTTP 200 logged SHA `204ee52e…83012`, but that blob is absent from disk. The final link-only guard cannot read the registered-role-holder proof and withholds it. Reconstructing this missing-file condition on the original link-only claim with valid evidence IDs withholds the site in both runtimes. A later targeted Defender log check confirmed detection and successful quarantine of this exact hash (events 1116/1117, Trojan:Script/Wacatac.H!ml); see [final small-item checks](final-small-items/REPORT.md). No project blob deletion or write-skip path was found. |','| BERGEN VAKTMESTERTJENESTER AS | 990412375 | https://bnv.no | New privacy-page bytes contain generated HTML `id="gap-943737207"`; the pre-existing raw identifier scan misreads this checksum-valid design ID as `foreign_orgnr`. Baseline privacy bytes lack it. Both main and corrected code accept the old page and reject the new page identically. This is a live-page-triggered pre-existing false positive, left open rather than weakening a veto in this verification. |','','The two runtime replay JSON files are identical. They record old/new body hashes and the raw element-ID excerpt; original responses and outputs were not edited. Peder Istad’s missing-body reconstruction is a diagnostic experiment, not a regenerated evaluator envelope.','','All seven highlighted sites are present live:','','| Company | Orgnr | Current URL | Proof |','|---|---|---|---|']
 for r in g['highlighted']:
  v=r['website'];assert v
  lines.append(f"| {r['company']} | {r['orgnr']} | {v['final_url']} | {v['proof_type']} |")
 lines+=['','Heiane Legesenter and Støren Dyreklinikk changed apex to www; the registered domain and ownership rule are unchanged. Støren’s proof body hash is identical. These are not company losses.','','### Gains and review gate','','Eight gained websites and nine new social profiles (five newly social companies) match exact company/URL entries already reviewed correct in `REVIEW.md`. There were **zero previously unreviewed gains**, zero wrong and zero doubtful inherited items. The current proof excerpts and links are in [gain-review-input.json](live-verification/gain-review-input.json); [review-result.json](live-verification/review-result.json) records the gate. New website proofs: orgnr 3, legal-name-plus-contact 1, registry phone 4. Sources: cc_index 3, legal-name guesses 5. No social platform was fetched.','','### Fresh-clone release refresh pair','','A new isolated local clone of `81086a9` installed with `uv sync --frozen`, with both bundled gzip indexes present (954,922 and 8,676,502 bytes). It used `bench/reports/release/orgnrs.txt` (103 lines: 100 valid and three invalid inputs), copied to `orgnrs.txt`. The literal README command ran twice against the same new `out/state`; outputs were archived before the second run. Credentials were stripped.','','| Run | Exit | Envelopes / profiles | HTTP | Company changes | Observation changes | Strict verifier exit |','|---|---:|---:|---:|---:|---:|---:|']
 for r in release['runs']:lines.append(f"| {r['number']} | {r['exit_code']} | 103 / 103 | {r['requests']} | {r['changes']} | {r['observation_changes']} | {r['strict_verifier_exit_code']} |")
 lines+=['','**Strict refresh-pair result: FAIL (`Claim IDs differ`), despite zero company changes.** A.U. Bygg AS (993581755) had a TimeoutError on `/kontakt-29389s.html` in run 1 and HTTP 200 on the same page in run 2. Five genuinely newly checked facts (two emails, one phone, two descriptions) produced five observation changes. The homepage bytes and company identity are unchanged. This transient network difference is preserved in [release-diagnosis.json](live-verification/release-diagnosis.json); no retries were run merely to obtain a passing pair. The unmodified verifier checks schemas, exact membership, stored body hashes, verbatim excerpts, synthesis, stable claim IDs and zero company/observation changes. See [execution](live-verification/release-execution.json) and the run verification logs. Both runs separately pass the unmodified schema/evidence verifier; the second standalone check is in `release-run2-evidence-verification.txt`. Only the strict refresh-pair stability check fails. No outputs, verifier assertions or test expectations were changed to make the gate pass.','','Full runtime suite: **1,259 passed in 658.85 s** (see [tests.json](live-verification/tests.json)). Measurement-only changes add release/loss replay scripts and extend job counting to include `hiring.site_job.*`, alongside `hiring.job.*`. Neither source runtime nor existing wrong-company tests changed. Main and fix-large-company-site refs remain untouched; nothing pushed.']
 marker='## Fresh live corrected verification'
 history=(OUT/'SCOREBOARD.md').read_text(encoding='utf8').split(marker)[0].rstrip()
 notice='Latest completed live verification: **112 websites, 48 social companies, 3 jobs companies, 1,000 activity companies** on corrected runtime `81086a9`. [Measured comparison and release refresh result (strict pair FAIL)](#fresh-live-corrected-verification--12-november-2026) below supersede the historical offline projection as the current result.'
 if notice not in history:history=history.replace('# R3 paired benchmark and complete source review','# R3 paired benchmark and complete source review\n\n'+notice,1)
 text=history+'\n\n'+'\n'.join(lines)+'\n'
 (OUT/'SCOREBOARD.md').write_text(text,encoding='utf8')
 print(json.dumps({'metrics':s['candidate'],'review':{k:v for k,v in review.items() if k not in ('highlighted_baseline_sites_retained','method')}},indent=2))
if __name__=='__main__':main()
